import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

sigmoid_source = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void sigmoid_kernel_fused(const float* __restrict__ input,
                                     float* __restrict__ output,
                                     int64_t n,
                                     int64_t n_vec4) {
    // Use 32-bit indexing for the main vectorized loop since the total
    // number of float4 elements (and remainder elements) comfortably
    // fits inside the int32 range for the target problem sizes. This
    // avoids costly 64-bit index arithmetic on every iteration and
    // reduces register pressure / improves instruction throughput.
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int stride = blockDim.x * gridDim.x;
    int n_vec4_i = static_cast<int>(n_vec4);
    const float4* __restrict__ in4 = reinterpret_cast<const float4*>(input);
    float4* __restrict__ out4 = reinterpret_cast<float4*>(output);
    #pragma unroll 4
    for (int i = idx; i < n_vec4_i; i += stride) {
        float4 in_val = __ldcs(&in4[i]);
        float4 out_val;
        out_val.x = 1.0f / (1.0f + __expf(-in_val.x));
        out_val.y = 1.0f / (1.0f + __expf(-in_val.y));
        out_val.z = 1.0f / (1.0f + __expf(-in_val.z));
        out_val.w = 1.0f / (1.0f + __expf(-in_val.w));
        __stcs(&out4[i], out_val);
    }
    int64_t rem_start64 = n_vec4 * 4;
    int rem_count = static_cast<int>(n - rem_start64);
    const float* __restrict__ in_rem = input + rem_start64;
    float* __restrict__ out_rem = output + rem_start64;
    for (int i = idx; i < rem_count; i += stride) {
        __stcs(&out_rem[i], 1.0f / (1.0f + __expf(-__ldcs(&in_rem[i]))));
    }
}
torch::Tensor sigmoid_cuda(torch::Tensor input) {
    auto input_contig = input.contiguous();
    auto output = torch::empty_like(input_contig);
    int64_t n = input_contig.numel();
    int64_t n_vec4 = n / 4;
    const int threads = 256;
    int64_t max_work = n_vec4 > (n - n_vec4 * 4) ? n_vec4 : (n - n_vec4 * 4);
    if (max_work == 0) {
        return output;
    }
    int64_t blocks = (max_work + threads - 1) / threads;
    if (blocks > 2147483647LL) blocks = 2147483647LL;
    if (blocks < 1) blocks = 1;
    sigmoid_kernel_fused<<<blocks, threads>>>(
        input_contig.data_ptr<float>(),
        output.data_ptr<float>(),
        n,
        n_vec4
    );
    return output;
}
"""
sigmoid_cpp_source = r"""
torch::Tensor sigmoid_cuda(torch::Tensor input);
"""
sigmoid_module = load_inline(
    name="sigmoid_module",
    cpp_sources=sigmoid_cpp_source,
    cuda_sources=sigmoid_source,
    functions=["sigmoid_cuda"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Optimized model that performs a Sigmoid activation using a custom CUDA kernel.
    """
    def __init__(self):
        super(ModelNew, self).__init__()
        self.sigmoid_cuda = sigmoid_module

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self.sigmoid_cuda.sigmoid_cuda(x)


